import app from 'flarum/forum/app';
import Modal from 'flarum/common/components/Modal';
import PollForm from './Poll/PollForm';
// Plain Modal, not FormModal: PollForm brings its own <form>.
export default class CreatePollModal extends Modal {
  title() {
    return app.translator.trans('fof-polls.forum.modal.add_title');
  }
  className() {
    return 'PollDiscussionModal Modal--medium';
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m(PollForm, {
      poll: this.attrs.poll,
      onsubmit: this.onFormSubmit.bind(this)
    }));
  }
  async onFormSubmit(data, state) {
    await this.attrs.onsubmit(data);
    this.hide();
  }
}
flarum.reg.add('fof-polls', 'forum/components/CreatePollModal', CreatePollModal);